import java.util.*;

class Playlist implements Cloneable {
    String name;
    List<String> songs = new ArrayList<>();
    Playlist(String name) { this.name = name; }
    @Override
    public Playlist clone() {
        try {
            Playlist p = (Playlist) super.clone();
            p.songs = new ArrayList<>(songs);
            return p;
        } catch (CloneNotSupportedException e) {
            throw new AssertionError(e);
        }
    }
}

public class Main {
    public static void main(String[] args) {
        Playlist a = new Playlist("road trip");
        a.songs.add("Song A");
        Playlist b = a.clone();
